  Widget _notificationIcon(BuildContext context) {
    return BlocBuilder<NotificationsBloc, NotificationsState>(
      bloc: getIt<NotificationsBloc>(),
      builder: (context, state) {
        final unread = state.maybeMap(
          loaded: (s) => s.unreadCount ?? 0,
          orElse: () => 0,
        );
        return Badge(
          isLabelVisible: unread > 0,
          label: Text(
            '$unread',
            style: TextStyle(fontSize: 12.sp),
          ),
          backgroundColor: Colors.red,
          child: IconButton(
            icon: Icon(
              unread > 0 ? Icons.notifications_active : Icons.notifications,
              size: 20.sp,
              color: Theme.of(context).colorScheme.primary,
            ),
            onPressed: () {
              // TODO: open notifications overlay similar to previous implementation
            },
          ),
        );
      },
    );
  }

